css:
.print-format { margin-top: 33mm; margin-bottom: 18mm; margin-left: 15mm; margin-right: 15mm; }
.print-format { margin: 0 !important; }
@page { size: A4; }
@media screen { #header-html, #footer-html { display: none; } }
.kya-letterhead { width:100%; border-collapse:collapse; border-bottom:0.8pt solid #999; margin-top:-12mm; }
.kya-letterhead td { vertical-align:middle; padding:0 0 1mm 0; font-size:7.8pt; line-height:1.25; color:#555; }
.kya-lh-logo { height:11mm; vertical-align:middle; margin-right:3mm; }
.kya-lh-name { font-weight:bold; font-size:10pt; color:#000; }
.kya-foot { width:100%; border-collapse:collapse; border-top:0.6pt solid #bbb; margin-top:-8mm; }
.kya-foot td { padding:1mm 0 0 0; vertical-align:bottom; }
.kya-foot-line { display:inline-block; border-bottom:1px solid #888; width:30mm; height:5mm; }
.kya-foot-cnss { font-size:7.5pt; color:#777; text-align:center; vertical-align:bottom; }
body { font-family: Arial, Helvetica, sans-serif; font-size: 11pt; color: #000; line-height: 1.45; }
.kya-pdf-page { padding: 0; }

/* En-tête officielle 3 colonnes : Logo | Titre orange | Meta */
.kya-contract-header {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 18px;
  table-layout: fixed;
}
.kya-contract-header td {
  border: 1px solid #6b6b6b;
  vertical-align: middle;
  padding: 0;
}
.kya-hdr-logo {
  width: 25%;
  text-align: center;
  padding: 4px 4px;
  background: #fff;
}
.kya-hdr-logo img {
  max-width: 150px;
  max-height: 110px;
  width: 100%;
  height: auto;
  display: block;
  margin: 0 auto;
}
.kya-hdr-title-cell {
  width: 50%;
  background: #F58220;
  color: #000;
  text-align: center;
  padding: 12px 8px;
}
.kya-hdr-title-text {
  font-weight: 900;
  font-size: 18pt;
  letter-spacing: 0.5px;
  line-height: 1.15;
  text-transform: uppercase;
  text-align: center;
  display: block;
  width: 100%;
}
.kya-hdr-ref-num {
  font-weight: 700;
  font-size: 12pt;
  margin-top: 6px;
}
.kya-hdr-meta {
  width: 25%;
  padding: 0;
  background: #fff;
}
.kya-hdr-meta .kya-meta-row {
  padding: 8px 10px;
  border-bottom: 1px solid #6b6b6b;
  font-size: 10.5pt;
  min-height: 18px;
}
.kya-hdr-meta .kya-meta-row:last-child { border-bottom: none; }
.kya-hdr-meta .kya-tagline {
  font-style: italic;
  font-weight: 700;
}

/* Corps */
.kya-corps {
  text-align: justify;
  font-size: 11pt;
  line-height: 1.5;
  margin: 14px 0 8px 0;
}
.kya-corps h2, .kya-corps h3, .kya-corps strong {
  color: #000;
}
.kya-corps p { margin: 6px 0; }
.kya-corps ul { margin: 4px 0 8px 18px; padding: 0; }
.kya-corps ul li { margin: 3px 0; }

/* Bloc 'Fait à Lomé le ...' */
.kya-fait-block {
  margin-top: 30px;
  margin-bottom: 22px;
}
.kya-fait-a {
  text-align: right;
  font-size: 11pt;
}

/* Bloc signatures : deux colonnes */
.kya-sig-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 24px;
  page-break-inside: avoid;
}
.kya-sig-table td {
  width: 50%;
  vertical-align: bottom;
  padding: 6px 12px;
}
.kya-sig-cell-left { text-align: left; }
.kya-sig-cell-right { text-align: left; padding-left: 30px; }
.kya-sig-img-wrap {
  min-height: 50px;
  margin-bottom: 2px;
}
.kya-sig-img {
  max-height: 60px;
  max-width: 200px;
}
.kya-sig-line {
  border-bottom: 1px solid #000;
  width: 240px;
  margin-bottom: 6px;
}
.kya-sig-label { font-size: 11pt; }
.kya-sig-name { font-size: 11pt; margin-top: 2px; }
.kya-sig-pour-kya { font-size: 10.5pt; margin-top: 4px; }

.kya-mention-note {
  margin-top: 10px;
  font-size: 10pt;
  font-style: italic;
}

.kya-footer-pdf {
  margin-top: 32px;
  padding-top: 6px;
  border-top: 1px solid #ccc;
  font-size: 9pt;
  color: #555;
  text-align: left;
}

html:
{%- set tpl_html = (frappe.db.get_value('KYA Contract Template', doc.template, 'html_body') if doc.template else '') -%}
{%- set logo_url = frappe.utils.get_url() + '/assets/kya_hr/images/kya_logo.png' -%}
{%- set ct = doc.contract_type or '' -%}
{%- set is_stage = ct.lower().startswith('stage') -%}
{%- set is_cdi = ct == 'CDI' -%}
{%- set is_cdd = ct == 'CDD' -%}
{%- set is_masc = doc.sexe == 'Masculin' -%}
{%- if is_cdi -%}
  {%- set titre_principal = 'CONTRAT DE TRAVAIL A DUREE INDETERMINEE' -%}
  {%- set ref_code = 'RH-ENG-06-V01' -%}
  {%- set type_short = 'CDI' -%}
{%- elif is_cdd -%}
  {%- set titre_principal = 'CONTRAT DE TRAVAIL A DUREE DETERMINEE' -%}
  {%- set ref_code = 'RH-ENG-06-V01' -%}
  {%- set type_short = 'CDD' -%}
{%- elif is_stage -%}
  {%- set titre_principal = 'CONTRAT DE STAGE' -%}
  {%- set ref_code = 'RH-ENG-07-V01' -%}
  {%- set type_short = 'STAGE' -%}
{%- else -%}
  {%- set titre_principal = ct|upper -%}
  {%- set ref_code = 'RH-ENG-06-V01' -%}
  {%- set type_short = 'CTR' -%}
{%- endif -%}
{%- set ref_date = doc.creation -%}
{%- set year_contrat = (doc.date_debut.year if doc.date_debut else (doc.creation.year if doc.creation else 2026)) -%}
{%- set name_parts = (doc.name or '').split('-') -%}
{%- set seq_num = name_parts[-1] if name_parts and name_parts[-1].isdigit() else '001' -%}
{%- set ref_num_official = (seq_num|int)|string -%}
{%- set ref_num_padded = '%03d' % (seq_num|int if seq_num.isdigit() else 1) -%}

<div class="kya-pdf-page">

  <div id="header-html"><table class="kya-letterhead"><tr><td style="width:50%;text-align:left;">08 BP 81101 AGOENYIVE, LOGOPE &middot; T&eacute;l. : +228 70 45 34 81 / 91 50 21 49</td><td style="width:50%;text-align:right;">N&deg; CFE : 6254PM2015/2015 &middot; N&deg; RCCM : TG-LOM 2015 B 975<br>NIF N&deg; 1000430317 &middot; R&Eacute;GIME FISCAL : R&eacute;el</td></tr></table></div>
  <div id="footer-html"><table class="kya-foot"><tr><td style="width:38%;text-align:left;"><span class="kya-foot-line">&nbsp;</span></td><td style="width:24%;" class="kya-foot-cnss">CNSS N&deg; 48863</td><td style="width:38%;text-align:right;"><span class="kya-foot-line">&nbsp;</span></td></tr></table><script>(function(){function h(){try{var q={},s=location.search.substring(1).split('&');for(var i=0;i<s.length;i++){var a=s[i].split('=');q[a[0]]=a[1];}if(q.page&&q.topage&&q.page===q.topage){var e=document.getElementsByClassName('kya-foot-line');for(var j=0;j<e.length;j++){e[j].style.display='none';}}}catch(x){}}if(document.readyState!=='loading'){h();}window.addEventListener('load',h);})();</script></div>

  <table class="kya-contract-header">
    <tr>
      <td class="kya-hdr-logo">
        <img src="{{ logo_url }}" alt="KYA-Energy Group">
      </td>
      <td class="kya-hdr-title-cell">
        <div class="kya-hdr-title-text">{{ titre_principal }}</div>
        <div class="kya-hdr-ref-num">N&deg; {{ ref_num_padded }}/{{ type_short }}/DG/{{ year_contrat }}</div>
      </td>
      <td class="kya-hdr-meta">
        <div class="kya-meta-row kya-tagline"><em>Move beyond the sky !</em></div>
        <div class="kya-meta-row">{{ ref_code }}</div>
        <div class="kya-meta-row">Date : {{ frappe.utils.formatdate(ref_date, 'dd/MM/yyyy') if ref_date else '' }}</div>
      </td>
    </tr>
  </table>

  <div class="kya-corps">
    {{ doc.get_corps_html() or ('<p><i>Template non configur&eacute; pour ' + ct + '. Cr&eacute;ez un KYA Contract Template avec des articles pour ce type.</i></p>') }}
  </div>

  <div class="kya-fait-block">
    <div class="kya-fait-a">Fait &agrave; Lom&eacute; le {% set _dd = doc.date_signature_dg or doc.date_signature_employe or doc.date_debut %}{% if _dd %}{% set _g = frappe.utils.getdate(_dd) %}{{ _g.day }} {{ ["","janvier","f&eacute;vrier","mars","avril","mai","juin","juillet","ao&ucirc;t","septembre","octobre","novembre","d&eacute;cembre"][_g.month] }} {{ _g.year }}{% else %}__________ 2026{% endif %}</div>
  </div>

  <table class="kya-sig-table">
    <tr>
      <td class="kya-sig-cell-left">
        <div class="kya-sig-img-wrap">
          {% if doc.signature_employe %}<img src="{{ doc.signature_employe }}" class="kya-sig-img">{% endif %}
        </div>
        <div class="kya-sig-line"></div>
        <div class="kya-sig-label"><strong>{% if is_stage %}{% if is_masc %}Le stagiaire{% else %}La stagiaire{% endif %}{% else %}{% if is_masc %}Le Salari&eacute;{% else %}La salari&eacute;e{% endif %}{% endif %}</strong></div>
        <div class="kya-sig-name"><strong>{% if is_masc %}M.{% else %}Mlle.{% endif %} {{ doc.employee_name or '' }}</strong> (*)</div>
      </td>
      <td class="kya-sig-cell-right">
        <div class="kya-sig-img-wrap">
          {% if doc.signature_dg %}<img src="{{ doc.signature_dg }}" class="kya-sig-img">{% endif %}
        </div>
        <div class="kya-sig-line"></div>
        <div class="kya-sig-label"><strong>{{ doc.fonction_dg or 'Le Directeur G&eacute;n&eacute;ral' }},</strong></div>
        <div class="kya-sig-name"><strong>{{ doc.nom_dg or 'Prof. Yao AZOUMAH' }}</strong></div>
        <div class="kya-sig-pour-kya">Pour KYA-Energy Group</div>
      </td>
    </tr>
  </table>

  <div class="kya-mention-note">(*) Signature pr&eacute;c&eacute;d&eacute;e de la mention manuscrite "lu et approuv&eacute;"</div>

  <div class="kya-footer-pdf">KYA-Energy Group /DG/ &ndash; R&eacute;f. {{ doc.name }}</div>

</div>
